tool.command:
{
printf 'LEGACY_VAR=%s\n' "\${LEGACY_VAR-unset}";
printf 'JOB_VAR=%s\n' "\${JOB_VAR-unset}";
printf 'TOOL_VAR=%s\n' "\${TOOL_VAR-unset}";
printf 'DECLARED_VAR=%s\n' "\${DECLARED_VAR-unset}";
printf 'EMPTY_VAR=%s\n' "\${EMPTY_VAR-unset}";
printf 'CONTAINER_VAR=%s\n' "\${CONTAINER_VAR-unset}";
} > '$out'
